import type { Dealer, Listing, Photo } from "@/lib/domain/types";
import { dealers } from "./dealers";
import { listingSpecs } from "./listings";
import photoData from "./photos.json";

export { dealers };

// Generated by scripts/seed-photos/build.py.
const photos: Record<string, Photo> = photoData;

/** Demo listings that have a photo. A spec without one is left out rather than shown blank. */
export const listings: Listing[] = listingSpecs.flatMap((spec) => {
  const photo = photos[spec.id];
  return photo ? [{ ...spec, photo }] : [];
});

/** A listing with its dealer, or null when either is missing. */
export function findListing(id: string): { listing: Listing; dealer: Dealer } | null {
  const listing = listings.find((candidate) => candidate.id === id);
  const dealer = listing ? dealers.find((candidate) => candidate.id === listing.dealerId) : undefined;
  return listing && dealer ? { listing, dealer } : null;
}
